import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<void> _loadDataFuture;

  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _loadDataFuture = _initData();
  }

  Future<void> _initData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    await Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()).then(
        (CurrencyPage page) => setState(() => _currencies = page.items),
      ),
      newsRepository
          .loadNewsFeed(const NewsFeedFilter(forceRefresh: true))
          .then((List<NewsModel> value) => setState(() => _news = value)),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<void>(
        future: _loadDataFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(
              child: SizedBox(
                width: 200,
                height: 4,
                child: LinearProgressIndicator(),
              ),
            );
          }

          return ListView.builder(
            itemCount: _currencies.length + _news.length + 1,
            itemBuilder: (BuildContext context, int index) {
              // Разделитель "Новости"
              if (index == _currencies.length && _news.isNotEmpty) {
                return Padding(
                  padding: const EdgeInsets.fromLTRB(22, 24, 22, 8),
                  child: Text(
                    context.loc.news,
                    style: context.fonts.semiBold16,
                  ),
                );
              }

              final int newsIndex = index - _currencies.length;
              if (index >= _currencies.length && _news.isNotEmpty) {
                final NewsModel news = _news[newsIndex];
                return Padding(
                  key: ValueKey(news.link),
                  padding: const EdgeInsets.fromLTRB(22, 8, 22, 0),
                  child: NewsCard(model: news),
                );
              }

              final CurrencyModel currency = _currencies[index];
              return Padding(
                key: ValueKey(currency.id),
                padding: index == 0
                    ? const EdgeInsets.fromLTRB(22, 16, 22, 8)
                    : const EdgeInsets.fromLTRB(22, 8, 22, 0),
                child: CurrencyCard(model: currency),
              );
            },
          );
        },
      ),
    );
  }
}
"}

