  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<void> _loadDataFuture;

  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _loadDataFuture = _initData();
  }

  Future<void> _initData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    await Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()).then(
        (CurrencyPage page) => setState(() => _currencies = page.items),
      ),
      newsRepository
          .loadNewsFeed(const NewsFeedFilter(forceRefresh: true))
          .then((List<NewsModel> value) => setState(() => _news = value)),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<void>(
        future: _loadDataFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(
              child: SizedBox(
                width: 200,
                height: 4,
                child: LinearProgressIndicator(),
              ),
            );
          }

          return ListView.builder(
            itemCount: _currencies.length + _news.length + (_news.isNotEmpty ? 1 : 0),
